🐛 Describe the bug
I was playing around to see if I could simulate multiple levels of forward AD with tensor wrappers but it doesn't work. One reason it doesn't work is that make_dual seems to silently lose tangents when you pass a (wrapped) dual tensor as argument to the primal.
import torch
from torch.utils._pytree import tree_map
import torch.autograd.forward_ad as fwAD

class WrapperTensor(torch.Tensor):
    @staticmethod
    def __new__(cls, e):
        r = torch.Tensor._make_wrapper_subclass(cls, e.shape, dtype=e.dtype, requires_grad=False)
        r.elem = e 
        return r 

    __torch_function__ = torch._C._disabled_torch_function_impl

    def __str__(self):
        return f'WrapperTensor({self.elem})'

    def __repr__(self):
        return str(self)

    @classmethod
    def __torch_dispatch__(cls, func, types, args=(), kwargs=None):  # type: ignore
        def unwrap(e):
            if isinstance(e, WrapperTensor):
                return e.elem
            else:
                return e 

        def wrap(e):
            if isinstance(e, torch.Tensor):
                return WrapperTensor(e)
            else:
                return e 

        return tree_map(wrap, func(*tree_map(unwrap, args), **tree_map(unwrap, kwargs)))

primal = torch.tensor(1)

with fwAD.dual_level():
    x = fwAD.make_dual(primal, torch.tensor(2))
    y = fwAD.make_dual(WrapperTensor(x), torch.tensor(3))
    print(fwAD.unpack_dual(y))

prints
UnpackedDualTensor(primal=WrapperTensor(1), tangent=tensor(3))

If you delete the WrapperTensor call you get
Traceback (most recent call last):
  File "/data/users/ezyang/pytorch-tmp/foo.py", line 40, in <module>
